	/* @Override */
	default  genReadLegToStack<THIS, N>/* where THIS : JitCompiledPassage where N : Next> Emitter<Ent<N, TInt> */(Emitter<N> em, Local<TRef<THIS>> localThis,
					JitCodeGenerator<THIS> gen, V v, MpIntJitType type, int leg, Ext ext) {
		Varnode vn = getVarnode(gen, v);
		if (vn.getSize() <= leg * Integer.BYTES) {
