		}
		Varnode subVn = JitDataFlowArithmetic.subPieceVn(gen.getAnalysisContext().getEndian(), vn,
			leg * Integer.BYTES, Integer.BYTES);
		return VarGen.genReadValDirectToStack(em, localThis, gen, type.legTypesLE().get(leg),
			subVn);
	}

